Object.assign(translations.es,{cityHint:'Lugares con historias publicadas',noSelection:'Explora el globo',loadingStories:'Cargando historias publicadas…',storiesError:'No se pudieron cargar las historias. Actualiza la página.',noStories:'Todavía no hay historias publicadas.',selectStoryPlace:'Elige un lugar para explorar historias.',chooseHint:'Elige un punto del globo, del mapa o de la lista de lugares.',fiction:'FICCIÓN'});

let places = [];

const canvas = $('#globe');
const ctx = canvas.getContext('2d');
const stage = $('.globe-stage');
const deg = Math.PI / 180;
const state = {lang:readLang(), lon:-50, lat:-15, selected:null, zoom:1, pointer:null, moved:false, outlines:null, notice:null, published:[],catalogStatus:'loading',regionalComments:[],view:'globe',map:null,mapMarker:null,storyLayer:null,mapZoom:12};
function readLang(){const path=location.pathname.split('/').filter(Boolean)[0];if(['pt','en','es'].includes(path))return path;const browserLanguage=(navigator.language||'en').toLowerCase();return browserLanguage.startsWith('pt')?'pt':browserLanguage.startsWith('es')?'es':'en'}
function t(key){return translations[state.lang][key]}
function fold(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
function wrap(lon){return ((lon+540)%360)-180}
function distance(a,b){const dlat=(b.lat-a.lat)*deg,dlon=(b.lon-a.lon)*deg,x=Math.sin(dlat/2)**2+Math.cos(a.lat*deg)*Math.cos(b.lat*deg)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function coordinates(pos){const digits=state.view==='map'?5:1;return `${Math.abs(pos.lat).toFixed(digits).replace('.',state.lang==='en'?'.':',')}° ${pos.lat<0?'S':'N'} · ${Math.abs(pos.lon).toFixed(digits).replace('.',state.lang==='en'?'.':',')}° ${pos.lon<0?(state.lang==='en'?'W':'O'):'E'}`}
function nearest(pos){return [...places].sort((a,b)=>distance(pos,a)-distance(pos,b))}
function storyPlaces(stories){const found=new Map();for(const story of stories){const place=story.place;if(!place||!Number.isFinite(place.latitude)||!Number.isFinite(place.longitude))continue;const id=[place.city,place.region,place.country].join('|');if(!found.has(id))found.set(id,{id,city:place.city,region:place.region,country:place.country,lat:place.latitude,lon:place.longitude})}return [...found.values()].sort((a,b)=>a.city.localeCompare(b.city,'pt-BR'))}
function locationName(pos){if(pos.city){let country=pos.country||pos.countryCode;try{if(pos.countryCode)country=new Intl.DisplayNames([{pt:'pt-BR',en:'en',es:'es'}[state.lang]],{type:'region'}).of(pos.countryCode)||country}catch{}return [pos.city,pos.region,country].filter(Boolean).join(', ')}const near=nearest(pos)[0];return near&&distance(pos,near)<80?[near.city,near.region,near.country].filter(Boolean).join(', '):coordinates(pos)}
function setNotice(message){state.notice=message;$('#notice').textContent=message||t('chooseHint')}
function select(pos,notice,mapZoom){cancelPlaceSearch();state.selected=pos;state.lon=pos.lon;state.lat=pos.lat;state.zoom=Math.max(1,state.zoom);setNotice(notice||null);renderResults();draw();if(state.view==='map'&&state.map){state.map.setView([pos.lat,pos.lon],mapZoom||state.map.getZoom());updateMapMarker()}}
function renderResults(){const pos=state.selected;
  $('#place').textContent=pos?locationName(pos):t('noSelection');
  $('#stories').replaceChildren();
  if(state.catalogStatus==='loading'){$('#summary').textContent=t('loadingStories')}
  else if(state.catalogStatus==='error'){$('#summary').textContent=t('storiesError')}
  else if(!state.published.length){$('#summary').textContent=t('noStories')}
  else if(pos){
    const records=[...state.published].sort((a,b)=>distance(pos,{lat:a.place.latitude,lon:a.place.longitude})-distance(pos,{lat:b.place.latitude,lon:b.place.longitude})).slice(0,3);
    $('#summary').textContent=`${records.length} ${t('publishedCount')}`;
    for(const story of records){const km=Math.round(distance(pos,{lat:story.place.latitude,lon:story.place.longitude}));const link=document.createElement('a');link.className='story';link.href=`/${state.lang}/${state.lang==='en'?'stories':'historias'}/${story.slug}/`;const meta=document.createElement('span');meta.className='story-meta';meta.textContent=`${t(story.classification)} · ${km.toLocaleString(state.lang==='en'?'en-US':state.lang==='es'?'es-ES':'pt-BR')} ${t('km')}`;const title=document.createElement('span');title.className='story-title';title.textContent=story.translations[state.lang].title;const subtitle=document.createElement('span');subtitle.className='story-location';subtitle.textContent=story.place.city;link.append(meta,title,subtitle);$('#stories').append(link)}
  }else{$('#summary').textContent=t('selectStoryPlace')}
  if(pos)renderRegional(pos);else $('#regional-comments').replaceChildren();
  $('#notice').textContent=state.notice||t('chooseHint');
  for(const button of $('#place-buttons').children)button.setAttribute('aria-pressed',String(pos?.id===button.dataset.id));
}
function renderRegional(pos){const list=$('#regional-comments');list.replaceChildren();const comments=state.regionalComments.map(item=>({item,km:distance(pos,{lat:item.latitude,lon:item.longitude})})).filter(entry=>entry.km<=250).sort((a,b)=>a.km-b.km).slice(0,3);if(!comments.length){const p=document.createElement('p');p.textContent=t('regionalEmpty');list.append(p);return}for(const {item,km} of comments){const entry=document.createElement('div');entry.className='regional-item';const name=document.createElement('strong');name.textContent=item.author;const region=document.createElement('small');region.textContent=`${item.city} · ${Math.round(km)} ${t('km')}`;const body=document.createElement('p');body.textContent=item.body;entry.append(name,region,body);list.append(entry)}}
function renderPlaces(){const datalist=$('#cities'),buttons=$('#place-buttons');datalist.replaceChildren();buttons.replaceChildren();for(const place of places){const option=document.createElement('option');option.value=place.city;datalist.append(option);const button=document.createElement('button');button.type='button';button.dataset.id=place.id;button.textContent=[place.city,place.region].filter(Boolean).join(', ');button.title=[place.city,place.region,place.country].filter(Boolean).join(', ');button.addEventListener('click',()=>select(place));buttons.append(button)}}
function localize(lang){state.lang=lang;document.documentElement.lang={pt:'pt-BR',en:'en',es:'es'}[lang];$('#language').value=lang;for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=t(el.dataset.i18n);for(const el of document.querySelectorAll('[data-placeholder]'))el.placeholder=t(el.dataset.placeholder);$('#search').setAttribute('aria-label',t('searchLabel'));$('#globe').setAttribute('aria-label',t('globeLabel'));$('#street-map').setAttribute('aria-label',t('mapLabel'));$('.view-switch').setAttribute('aria-label',t('viewLabel'));$('#globe-panel').setAttribute('aria-label',t('placeLabel'));$('.gesture').textContent=t(state.view==='map'?'mapGesture':'gesture');$('#zoom-in').setAttribute('aria-label',t('zoomIn'));$('#zoom-out').setAttribute('aria-label',t('zoomOut'));$('#zoom-in').title=t('zoomIn');$('#zoom-out').title=t('zoomOut');$('.brand').href=`/${lang}/`;$('#privacy-link').href=`/${lang}/privacidade.html`;document.title=t('metaTitle');document.querySelector('meta[name=description]').content=t('metaDescription');$('#coordinates').textContent=coordinates(state);renderPlaces();state.notice=null;renderResults();renderStoryMarkers();draw()}

const LEAFLET_JS='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js';
const LEAFLET_CSS='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css';
// Load the detailed map only when the visitor requests it; map tiles reveal the viewed area to OSM.
let leafletLoad;
function loadLeaflet(){if(leafletLoad)return leafletLoad;leafletLoad=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href=LEAFLET_CSS;css.onerror=()=>reject(Error('Leaflet CSS unavailable'));document.head.append(css);const script=document.createElement('script');script.src=LEAFLET_JS;script.onload=()=>window.L?resolve(window.L):reject(Error('Leaflet unavailable'));script.onerror=()=>reject(Error('Leaflet unavailable'));document.head.append(script)});return leafletLoad}
function updateMapMarker(){if(!state.map||!state.selected)return;const at=[state.selected.lat,state.selected.lon];if(!state.mapMarker){state.mapMarker=window.L.circleMarker(at,{radius:8,color:'#fff0cf',weight:2,fillColor:'#bb9458',fillOpacity:1}).addTo(state.map)}else state.mapMarker.setLatLng(at)}
function renderStoryMarkers(){if(!state.map)return;const L=window.L;if(state.storyLayer)state.storyLayer.clearLayers();else state.storyLayer=L.layerGroup().addTo(state.map);for(const story of state.published){const {latitude,longitude}=story.place;const marker=L.circleMarker([latitude,longitude],{radius:7,color:'#f4d4a0',weight:2,fillColor:'#733d32',fillOpacity:.95,bubblingMouseEvents:false}).addTo(state.storyLayer);const panel=document.createElement('div');panel.className='story-map-popup';const title=document.createElement('strong');title.textContent=story.translations[state.lang].title;const place=document.createElement('span');place.textContent=story.place.city;const link=document.createElement('a');link.href=`/${state.lang}/${state.lang==='en'?'stories':'historias'}/${encodeURIComponent(story.slug)}/`;link.textContent=t('readStory');panel.append(title,place,link);marker.bindPopup(panel);marker.bindTooltip(story.translations[state.lang].title,{direction:'top'})}}
async function showMap(){if(state.view==='map')return;setNotice(t('mapLoading'));try{const L=await loadLeaflet();state.view='map';canvas.hidden=true;$('#street-map').hidden=false;$('#view-globe').setAttribute('aria-pressed','false');$('#view-map').setAttribute('aria-pressed','true');$('.gesture').textContent=t('mapGesture');if(!state.map){state.map=L.map('street-map',{zoomControl:false,scrollWheelZoom:true,maxZoom:19}).setView([state.lat,state.lon],state.mapZoom);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap</a> contributors'}).addTo(state.map);state.map.on('click',({latlng})=>select({lat:latlng.lat,lon:latlng.lng},t('mapChoice')));state.map.on('zoomend',()=>{state.mapZoom=state.map.getZoom()})}state.map.invalidateSize();state.map.setView([state.lat,state.lon],state.mapZoom);updateMapMarker();renderStoryMarkers();$('#coordinates').textContent=coordinates(state);setNotice(t('mapChoice'))}catch{setNotice(t('mapUnavailable'))}}
function showGlobe(){if(state.view==='globe')return;state.view='globe';$('#street-map').hidden=true;canvas.hidden=false;$('#view-globe').setAttribute('aria-pressed','true');$('#view-map').setAttribute('aria-pressed','false');$('.gesture').textContent=t('gesture');setNotice(null);draw()}

function project(lon,lat,r,cx,cy){const lambda=wrap(lon-state.lon)*deg,phi=lat*deg,phi0=state.lat*deg;const visible=Math.sin(phi0)*Math.sin(phi)+Math.cos(phi0)*Math.cos(phi)*Math.cos(lambda);return {x:cx+r*Math.cos(phi)*Math.sin(lambda),y:cy-r*(Math.cos(phi0)*Math.sin(phi)-Math.sin(phi0)*Math.cos(phi)*Math.cos(lambda)),visible:visible>=0}}
function drawLine(points,r,cx,cy,color,width){ctx.beginPath();let previous=null;for(const [lon,lat] of points){const p=project(lon,lat,r,cx,cy);if(p.visible){if(previous&&previous.visible&&Math.abs(p.x-previous.x)<r*.5&&Math.abs(p.y-previous.y)<r*.5)ctx.lineTo(p.x,p.y);else ctx.moveTo(p.x,p.y)}previous=p}ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function draw(){if(!ctx){$('#globe-error').hidden=false;return}const box=stage.getBoundingClientRect(),w=box.width,h=box.height;if(!w||!h)return;const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const cx=w/2,cy=h/2,r=Math.min(w*.43,h*.46)*state.zoom;const glow=ctx.createRadialGradient(cx-r*.25,cy-r*.32,r*.08,cx,cy,r*1.4);glow.addColorStop(0,'#29495a');glow.addColorStop(.58,'#163043');glow.addColorStop(1,'#08121c');ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill();ctx.strokeStyle='#79919a';ctx.lineWidth=1.25;ctx.stroke();ctx.save();ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.clip();for(let lon=-180;lon<=180;lon+=15){const line=[];for(let lat=-90;lat<=90;lat+=2)line.push([lon,lat]);drawLine(line,r,cx,cy,'#6e8b99',.45)}for(let lat=-75;lat<=75;lat+=15){const line=[];for(let lon=-180;lon<=180;lon+=2)line.push([lon,lat]);drawLine(line,r,cx,cy,'#6e8b99',.45)}if(state.outlines)for(const line of state.outlines)drawLine(line,r,cx,cy,'#9bb0a8',.75);for(const place of places){const p=project(place.lon,place.lat,r,cx,cy);if(p.visible){ctx.beginPath();ctx.arc(p.x,p.y,place.id===state.selected?.id?4.2:2.8,0,Math.PI*2);ctx.fillStyle='#d7b77b';ctx.fill()}}if(state.selected){const marker=project(state.selected.lon,state.selected.lat,r,cx,cy);if(marker.visible){ctx.beginPath();ctx.arc(marker.x,marker.y,12,0,Math.PI*2);ctx.fillStyle='#d7b77b30';ctx.fill();ctx.beginPath();ctx.arc(marker.x,marker.y,4.3,0,Math.PI*2);ctx.fillStyle='#f5d397';ctx.fill()}}ctx.restore();$('#coordinates').textContent=coordinates(state)}

// Decode the published Natural Earth world-atlas TopoJSON into longitude/latitude outlines.
function topoLines(topology){const scale=topology.transform.scale,translate=topology.transform.translate,cache=new Map();function arc(index){const id=index<0?~index:index;if(!cache.has(id)){let x=0,y=0;cache.set(id,topology.arcs[id].map(([dx,dy])=>{x+=dx;y+=dy;return[x*scale[0]+translate[0],y*scale[1]+translate[1]]}))}const coords=cache.get(id);return index<0?[...coords].reverse():coords}function ring(indices){return indices.flatMap((index,i)=>{const line=arc(index);return i?line.slice(1):line})}const lines=[];function collect(geometry){if(geometry.type==='Polygon')for(const indices of geometry.arcs)lines.push(ring(indices));else if(geometry.type==='MultiPolygon')for(const polygon of geometry.arcs)for(const indices of polygon)lines.push(ring(indices));else if(geometry.type==='GeometryCollection')geometry.geometries.forEach(collect)}collect(topology.objects.countries);return lines}
fetch('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json').then(response=>{if(!response.ok)throw Error('map unavailable');return response.json()}).then(data=>{state.outlines=topoLines(data);draw()}).catch(()=>{draw()});

let searchController=null,searchSequence=0;
function cancelPlaceSearch(){searchSequence++;searchController?.abort();searchController=null;$('#search-results').replaceChildren();$('#search-results').hidden=true}
function placeTitle(place){return [place.name,place.admin1,place.country].filter(Boolean).join(', ')}
$('#search').addEventListener('input',cancelPlaceSearch);
$('#search-form').addEventListener('submit',async event=>{
  event.preventDefault();cancelPlaceSearch();const query=$('#search').value.trim();if(query.length<2){setNotice(t('searchShort'));return}
  const exact=places.find(place=>[place.city,[place.city,place.region].join(', '),[place.city,place.region,place.country].join(', ')].some(name=>fold(name)===fold(query)));
  if(exact){select(exact,null,12);$('#search').value='';return}
  const sequence=searchSequence;searchController=new AbortController();setNotice(t('searching'));
  try{
    const url=new URL('https://geocoding-api.open-meteo.com/v1/search');url.search=new URLSearchParams({name:query,count:'6',language:state.lang,format:'json'}).toString();
    const response=await fetch(url,{signal:searchController.signal});if(!response.ok)throw Error('geocoding unavailable');const data=await response.json();if(sequence!==searchSequence)return;
    const found=(Array.isArray(data.results)?data.results:[]).filter(item=>Number.isFinite(item.latitude)&&Number.isFinite(item.longitude)&&typeof item.name==='string');
    if(!found.length){setNotice(t('searchNone'));return}
    const list=$('#search-results');const heading=document.createElement('p');heading.textContent=t('searchChoices');list.append(heading);
    for(const item of found){const button=document.createElement('button');button.type='button';button.textContent=placeTitle(item);button.addEventListener('click',()=>{select({lat:item.latitude,lon:item.longitude,city:item.name,region:item.admin1||'',countryCode:item.country_code,country:item.country},null,12);$('#search').value='' });list.append(button)}
    list.hidden=false;setNotice(t('searchChoices'));
  }catch(error){if(error.name!=='AbortError'&&sequence===searchSequence)setNotice(t('searchError'))}finally{if(sequence===searchSequence)searchController=null}
});
$('#language').addEventListener('change',event=>{cancelPlaceSearch();const value=event.target.value;history.pushState(null,'',`/${value}/`);localize(value)});
window.addEventListener('popstate',()=>localize(readLang()));
$('#locate').addEventListener('click',()=>{if(!navigator.geolocation){setNotice(t('locateFail'));return}setNotice(t('locatePending'));navigator.geolocation.getCurrentPosition(({coords})=>select({lon:coords.longitude,lat:coords.latitude},t('locateSuccess')),()=>setNotice(t('locateFail')),{enableHighAccuracy:false,timeout:9000,maximumAge:300000})});
$('#view-map').addEventListener('click',showMap);$('#view-globe').addEventListener('click',showGlobe);
$('#zoom-in').addEventListener('click',()=>{if(state.view==='map'){state.map?.zoomIn();return}state.zoom=Math.min(1.65,state.zoom*1.2);draw()});$('#zoom-out').addEventListener('click',()=>{if(state.view==='map'){state.map?.zoomOut();return}state.zoom=Math.max(.8,state.zoom/1.2);draw()});
stage.addEventListener('wheel',event=>{
  if(state.view==='map')return;
  event.preventDefault();
  const pixels=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?stage.clientHeight:1);
  state.zoom=Math.max(.8,Math.min(1.65,state.zoom*Math.exp(-pixels*.0015)));
  draw();
},{passive:false});
canvas.addEventListener('pointerdown',event=>{canvas.setPointerCapture(event.pointerId);state.pointer={x:event.clientX,y:event.clientY,startX:event.clientX,startY:event.clientY};state.moved=false});
canvas.addEventListener('pointermove',event=>{if(!state.pointer)return;const dx=event.clientX-state.pointer.x,dy=event.clientY-state.pointer.y;if(Math.hypot(event.clientX-state.pointer.startX,event.clientY-state.pointer.startY)>5)state.moved=true;const radius=Math.min(stage.clientWidth*.43,stage.clientHeight*.46)*state.zoom;state.lon=wrap(state.lon-dx*90/radius);state.lat=Math.max(-85,Math.min(85,state.lat+dy*90/radius));state.pointer.x=event.clientX;state.pointer.y=event.clientY;draw()});
canvas.addEventListener('pointerup',event=>{if(!state.pointer)return;const moved=state.moved;state.pointer=null;if(moved)return;const box=canvas.getBoundingClientRect(),x=event.clientX-box.left-box.width/2,y=event.clientY-box.top-box.height/2,r=Math.min(stage.clientWidth*.43,stage.clientHeight*.46)*state.zoom;const rho=Math.hypot(x,y);if(rho>r)return;const hit=places.find(place=>{const point=project(place.lon,place.lat,r,box.width/2,box.height/2);return point.visible&&Math.hypot(point.x-box.width/2-x,point.y-box.height/2-y)<10});if(hit){select(hit);return}const c=Math.asin(Math.min(1,rho/r)),phi0=state.lat*deg;const lat=rho===0?state.lat:Math.asin(Math.cos(c)*Math.sin(phi0)-y*Math.sin(c)*Math.cos(phi0)/rho)/deg;const lon=rho===0?state.lon:state.lon+Math.atan2(x*Math.sin(c),rho*Math.cos(phi0)*Math.cos(c)+y*Math.sin(phi0)*Math.sin(c))/deg;select({lon:wrap(lon),lat})});
canvas.addEventListener('pointercancel',()=>{state.pointer=null});

new ResizeObserver(draw).observe(stage);localize(state.lang);
fetch('/api/stories').then(response=>{if(!response.ok)throw Error('catalog unavailable');return response.json()}).then(({stories})=>{state.published=Array.isArray(stories)?stories:[];places=storyPlaces(state.published);state.catalogStatus='ready';renderPlaces();if(!state.selected&&places.length)select(places[0]);else{renderResults();draw()}renderStoryMarkers()}).catch(()=>{state.catalogStatus='error';renderResults()});
fetch('/api/comments/regions').then(response=>response.ok?response.json():{comments:[]}).then(({comments})=>{state.regionalComments=Array.isArray(comments)?comments:[];if(state.selected)renderRegional(state.selected)}).catch(()=>{});
